404	    /**
405	     * Returns {@link BidderPrivacyResult} with GDPR masking.
406	     */
407	    private BidderPrivacyResult createBidderPrivacyResult(User user,
408	                                                          Device device,
409	                                                          String bidder,
410	                                                          boolean isLmtEnabled,
411	                                                          Map<String, PrivacyEnforcementAction> bidderToEnforcement) {
412	
413	        final PrivacyEnforcementAction privacyEnforcementAction = bidderToEnforcement.get(bidder);
414	        final boolean blockBidderRequest = privacyEnforcementAction.isBlockBidderRequest();
415	        final boolean blockAnalyticsReport = privacyEnforcementAction.isBlockAnalyticsReport();
416	        if (blockBidderRequest) {
417	            return BidderPrivacyResult.builder()
418	                    .requestBidder(bidder)
419	                    .blockedRequestByTcf(true)
420	                    .blockedAnalyticsByTcf(blockAnalyticsReport)
421	                    .build();
422	        }
423	
424	        final boolean maskGeo = privacyEnforcementAction.isMaskGeo() || isLmtEnabled;
425	        final boolean maskUserIds = privacyEnforcementAction.isRemoveUserIds() || isLmtEnabled;
426	        final User maskedUser = maskTcfUser(user, maskUserIds, maskGeo);
427	
428	        final boolean maskIp = privacyEnforcementAction.isMaskDeviceIp() || isLmtEnabled;
429	        final boolean maskInfo = privacyEnforcementAction.isMaskDeviceInfo() || isLmtEnabled;
430	        final Device maskedDevice = maskTcfDevice(device, maskIp, maskGeo, maskInfo);
431	
432	        return BidderPrivacyResult.builder()
433	                .requestBidder(bidder)
434	                .user(maskedUser)
435	                .device(maskedDevice)
436	                .blockedAnalyticsByTcf(blockAnalyticsReport)
437	                .build();
